SELECT json_object('nulls',sum("id" IS NULL),'distinct',count(DISTINCT "id"),'nonempty',sum("id" IS NOT NULL AND CAST("id" AS TEXT)<>'')) AS "id",json_object('nulls',sum("name" IS NULL),'distinct',count(DISTINCT "name"),'nonempty',sum("name" IS NOT NULL AND CAST("name" AS TEXT)<>'')) AS "name",json_object('nulls',sum("role" IS NULL),'distinct',count(DISTINCT "role"),'nonempty',sum("role" IS NOT NULL AND CAST("role" AS TEXT)<>'')) AS "role",json_object('nulls',sum("is_active" IS NULL),'distinct',count(DISTINCT "is_active"),'nonempty',sum("is_active" IS NOT NULL AND CAST("is_active" AS TEXT)<>'')) AS "is_active",json_object('nulls',sum("created_at" IS NULL),'distinct',count(DISTINCT "created_at"),'nonempty',sum("created_at" IS NOT NULL AND CAST("created_at" AS TEXT)<>'')) AS "created_at",json_object('nulls',sum("updated_at" IS NULL),'distinct',count(DISTINCT "updated_at"),'nonempty',sum("updated_at" IS NOT NULL AND CAST("updated_at" AS TEXT)<>'')) AS "updated_at" FROM "user_profiles";
SELECT json_object('nulls',sum("source_key" IS NULL),'distinct',count(DISTINCT "source_key"),'nonempty',sum("source_key" IS NOT NULL AND CAST("source_key" AS TEXT)<>'')) AS "source_key",json_object('nulls',sum("payload" IS NULL),'distinct',count(DISTINCT "payload"),'nonempty',sum("payload" IS NOT NULL AND CAST("payload" AS TEXT)<>'')) AS "payload" FROM "sheet_import_sources";